// src/ui/operation-results.ts
function renderOperationSummary(container, summary, options = {}) {
  container.empty();
  container.createEl("h4", { text: "Operation results" });
  container.createDiv({
    cls: "templar-operation-summary-counts",
    text: `Succeeded: ${String(summary.succeeded)} \xB7 Failed: ${String(summary.failed)} \xB7 Skipped: ${String(summary.skipped)} \xB7 Warnings: ${String(summary.warnings)}`
  });
  const visibleResults = summary.results.filter(
    (result2) => result2.status !== "succeeded" || result2.warnings.length > 0
  );
  if (options.showPaths && visibleResults.length > 0) {
    const list2 = container.createEl("ul", { cls: "templar-operation-results" });
    for (const result2 of visibleResults) {
      const details = result2.warnings.map((warning) => warning.message).join(" ");
      const suffix = result2.message ? ` ${result2.message}` : "";
      list2.createEl("li", {
        text: `${result2.status}: ${result2.path}${suffix}${details ? ` ${details}` : ""}`
      });
    }
  }
}

